CREATE TABLE "sms_configurations" ("id" TEXT PRIMARY KEY, "adapter_id" TEXT NOT NULL, "from" TEXT NOT NULL, "fallback_configuration_ids" JSONB NOT NULL, "rate_limit_max" INTEGER NOT NULL CHECK ("rate_limit_max" > 0), "rate_limit_window_seconds" INTEGER NOT NULL CHECK ("rate_limit_window_seconds" > 0), "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "sms_templates" ("id" TEXT PRIMARY KEY, "body_template" TEXT NOT NULL, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "sms_deliveries" ("id" UUID PRIMARY KEY, "configuration_id" TEXT NOT NULL, "recipient" TEXT NOT NULL, "purpose" TEXT NOT NULL, "unsubscribe_topic" TEXT, "idempotency_key" TEXT, "status" "email_delivery_status" NOT NULL, "rendered_body" TEXT NOT NULL, "provider_message_id" TEXT, "failure_code" TEXT, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "sent_at" TIMESTAMPTZ(3));
CREATE INDEX "sms_deliveries_recipient_created_at_idx" ON "sms_deliveries"("recipient", "created_at"); CREATE UNIQUE INDEX "sms_deliveries_recipient_idempotency_key_unique" ON "sms_deliveries"("recipient", "idempotency_key") WHERE "idempotency_key" IS NOT NULL;
CREATE TABLE "sms_subscriptions" ("recipient" TEXT NOT NULL, "topic" TEXT NOT NULL, "unsubscribed_at" TIMESTAMPTZ(3), PRIMARY KEY ("recipient", "topic"));
CREATE TABLE "notification_configurations" ("id" TEXT PRIMARY KEY, "adapter_id" TEXT NOT NULL, "fallback_configuration_ids" JSONB NOT NULL, "rate_limit_max" INTEGER NOT NULL CHECK ("rate_limit_max" > 0), "rate_limit_window_seconds" INTEGER NOT NULL CHECK ("rate_limit_window_seconds" > 0), "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL);
CREATE TABLE "notification_devices" ("id" TEXT PRIMARY KEY, "recipient_id" TEXT NOT NULL, "adapter_id" TEXT NOT NULL, "endpoint" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" TIMESTAMPTZ(3) NOT NULL); CREATE INDEX "notification_devices_recipient_id_active_idx" ON "notification_devices"("recipient_id", "active");
CREATE TABLE "notification_deliveries" ("id" UUID PRIMARY KEY, "configuration_id" TEXT NOT NULL, "device_id" TEXT NOT NULL, "recipient_id" TEXT NOT NULL, "purpose" TEXT NOT NULL, "unsubscribe_topic" TEXT, "idempotency_key" TEXT, "status" "email_delivery_status" NOT NULL, "title" TEXT NOT NULL, "body" TEXT NOT NULL, "data" JSONB NOT NULL, "provider_message_id" TEXT, "failure_code" TEXT, "created_at" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "sent_at" TIMESTAMPTZ(3)); CREATE INDEX "notification_deliveries_recipient_id_created_at_idx" ON "notification_deliveries"("recipient_id", "created_at"); CREATE UNIQUE INDEX "notification_deliveries_device_id_idempotency_key_unique" ON "notification_deliveries"("device_id", "idempotency_key") WHERE "idempotency_key" IS NOT NULL;
CREATE TABLE "notification_subscriptions" ("recipient_id" TEXT NOT NULL, "topic" TEXT NOT NULL, "unsubscribed_at" TIMESTAMPTZ(3), PRIMARY KEY ("recipient_id", "topic"));
